#include <moe_topk/protocol_i_pipeline.h>
#include <moe_topk/protocol_i_transport.h>
#include <stdexcept>
namespace moe_topk { namespace {
void require(bool ok,const char* what){if(!ok)throw std::invalid_argument(what);}std::vector<std::uint8_t> enc(const std::vector<std::uint64_t>&v){std::vector<std::uint8_t>b;for(auto x:v)for(int s=56;s>=0;s-=8)b.push_back(static_cast<std::uint8_t>(x>>s));return b;}std::vector<std::uint64_t> dec(const std::vector<std::uint8_t>&b){require(b.size()%8==0,"rank frame length");std::vector<std::uint64_t>v(b.size()/8);for(std::size_t i=0;i<v.size();++i)for(int j=0;j<8;++j)v[i]=(v[i]<<8)|b[8*i+j];return v;}
}
ProtocolIPriorityPipelineOutput protocol_i_priority_pipeline_party(const ProtocolIPriorityPipelineConfig& c,ProtocolIPartyPackage&& p,ProtocolIShufflePartyMaterial& m,const std::vector<std::uint64_t>& keys,const std::array<int,2>& ff,int cmp,int reveal,const std::array<int,2>& rf){require(c.party<2&&c.n>=2&&c.k>0&&c.k<=c.n&&c.comparison_bits>=34&&keys.size()==c.n,"pipeline config");require(p.party==c.party&&p.n==c.n&&p.k==c.k&&p.comparison_bits==c.comparison_bits&&p.session==c.session&&p.fingerprint==c.fingerprint,"pipeline package");const auto ring=(UINT64_C(1)<<c.comparison_bits)-1U;std::vector<ProtocolIBlock192> record(c.n);for(std::size_t i=0;i<c.n;++i)record[i]={keys[i],0,0};const auto forward=protocol_i_shuffle_forward_party(c.party,ff,record,m);std::vector<std::uint64_t> local(c.n);for(std::size_t i=0;i<c.n;++i)local[i]=(forward.share[i].word0+p.node_mask_shares[i])&ring;ProtocolIFrameConfig fc{c.session,c.fingerprint,c.n,c.k,c.comparison_bits,c.party,static_cast<std::uint8_t>(1-c.party),2,1};ProtocolIFramedChannel channel(cmp,fc,c.timeout_ms);if(c.party==0)channel.send(enc(local));const auto peer=dec(channel.receive());if(c.party==1)channel.send(enc(local));require(peer.size()==c.n,"cmp frame");std::vector<std::uint64_t> opened(c.n);for(std::size_t i=0;i<c.n;++i)opened[i]=(local[i]+peer[i])&ring;std::vector<ProtocolIUcmpPartyMaterial> edge;for(auto&e:p.edge_materials)edge.push_back(std::move(e.material));const auto ranks=protocol_i_cmpagg_eval_party(c.party,c.comparison_bits,opened,edge);ProtocolIFrameConfig rc{c.session,c.fingerprint,c.n,c.k,c.comparison_bits,c.party,static_cast<std::uint8_t>(1-c.party),3,1};ProtocolIFramedChannel reveal_channel(reveal,rc,c.timeout_ms);const auto raw=enc(ranks);if(c.party==0)reveal_channel.send(raw);const auto peer_rank=dec(reveal_channel.receive());if(c.party==1)reveal_channel.send(raw);require(peer_rank.size()==c.n,"rank reveal");std::vector<ProtocolIBlock192> carrier(c.n);for(std::size_t i=0;i<c.n;++i){const auto rank=ranks[i]+peer_rank[i];require(rank<c.n,"rank range");carrier[i]={c.party==0&&rank<c.k?1U:0U,0,0};}const auto reverse=protocol_i_shuffle_reverse_party(c.party,rf,carrier,m);ProtocolIPriorityPipelineOutput out;out.xor_mask_share.resize(c.n);for(std::size_t i=0;i<c.n;++i)out.xor_mask_share[i]=static_cast<std::uint8_t>(reverse.share[i].word0&1U);return out;}
}  // namespace moe_topk
